import numpy as np

# Check for pairs of isolated cells in same row/column
demo_lines = [line.split() for line in demo_input.strip().split('\n')]
demo_grid = np.array([list(map(int, row)) for row in demo_lines])

h, w = demo_grid.shape

# Find all isolated non-zero cells (cells where both horizontal and vertical neighbors are 0)
def find_isolated(grid):
    h, w = grid.shape
    isolated = []
    for r in range(h):
        for c in range(w):
            if grid[r, c] == 0:
                continue
            has_above = grid[r-1,c] != 0 if r > 0 else False
            has_below = grid[r+1,c] != 0 if r < h-1 else False
            has_left = grid[r,c-1] != 0 if c > 0 else False
            has_right = grid[r,c+1] != 0 if c < w-1 else False
            # Isolated means no orthogonal neighbors
            if not (has_above or has_below or has_left or has_right):
                isolated.append((r, c, int(grid[r,c])))
    return isolated

isolate_demo = find_isolated(demo_grid)
print(f"Isolated cells in demo: {isolate_demo}")

# Now check for pairs in same row/col
from collections import defaultdict
row_pairs = defaultdict(list)
col_pairs = defaultdict(list)
for r, c, val in isolate_demo:
    row_pairs[r].append(c)
    col_pairs[c].append(r)

print("\nRow pairs of isolated cells:")
for r, cols in sorted(row_pairs.items()):
    print(f"  Row {r}: cols {cols}")

print("\nColumn pairs of isolated cells:")
for c, rows in sorted(col_pairs.items()):
    print(f"  Col {c}: rows {rows}")

# Now let's check what actually happened in the output
# A pair creates a fill between them
print("\nPredicted fills based on pairs:")
predicted_filled = set()
for r, cols in sorted(row_pairs.items()):
    for i in range(len(cols)-1):
        for j in range(i+1, len(cols)):
            start, end = min(cols[i], cols[j]), max(cols[i], cols[j])
            for c in range(start, end+1):
                predicted_filled.add((r, c))
for c, rows in sorted(col_pairs.items()):
    for i in range(len(rows)-1):
        for j in range(i+1, len(rows)):
            start, end = min(rows[i], rows[j]), max(rows[i], rows[j])
            for r in range(start, end+1):
                predicted_filled.add((r, c))

print(f"\nPredicted filled positions ({len(predicted_filled)}):")
sorted_pred = sorted(predicted_filled)
for pos in sorted_pred[:20]:
    print(f"  {pos}"), f"... {len(sorted_pred)-20} more")

