import numpy as np
from collections import defaultdict

# Re-analyze more carefully - focus on which component stays as what value
demo_input_lines = [line.split() for line in demo_input_str.strip().split('\n')]
demo_grid = np.array([list(map(int, row)) for row in demo_input_lines])

output_lines = [line.split() for line in demo_output_str.strip().split('\n')]
demo_output = np.array([list(map(int, row)) for row in output_lines])

def find_components(grid):
    h, w = grid.shape
    visited = np.zeros((h, w), dtype=bool)
    components = []

    def bfs(r, c):
        queue = [(r, c)]
        comp_cells = []
        while queue:
            cr, cc = queue.pop(0)
            if visited[cr, cc]:
                continue
            visited[cr, cc] = True
            comp_cells.append((cr, cc))
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < h and 0 <= nc < w and not visited[nr, nc] and grid[nr, nc] != 0:
                    queue.append((nr, nc))
        return comp_cells

    for r in range(h):
        for c in range(w):
            if grid[r, c] != 0 and not visited[r, c]:
                cells = bfs(r, c)
                if len(cells) > 0:
                    components.append({
                        'cells': cells,
                        'min_r': min(x[0] for x in cells),
                        'max_r': max(x[0] for x in cells),
                        'min_c': min(x[1] for x in cells),
                        'max_c': max(x[1] for x in cells),
                        'size': len(cells),
                        'value': int(grid[min(x[0] for x in cells)][min(x[1] for x in cells)])
                    })
    return components

