import copy

def apply_full_transform(grid_in):
    """Apply full transformation including fill lines and component changes"""
    grid = copy.deepcopy(grid_in)

    # Find all isolated cells
    isolates = find_isolates(grid)

    # Determine fill lines
    fill_rows = set()
    fill_cols = set()

    row_counts = {}
    for r, c in isolates:
        row_counts[r] = row_counts.get(r, 0) + 1
    for r, cnt in row_counts.items():
        if cnt >= 2:
            fill_rows.add(r)

    col_counts = {}
    for r, c in isolates:
        col_counts[c] = col_counts.get(c, 0) + 1
    for c, cnt in col_counts.items():
        if cnt >= 2:
            fill_cols.add(c)

    print(f"Isolates: {isolates}")
    print(f"Fill rows: {fill_rows}, Fill cols: {fill_cols}")

    # Apply fills first (before checking components)
    rows, cols = len(grid), len(grid[0])
    for r in fill_rows:
        for c in range(cols):
            grid[r][c] = 1

    for c in fill_cols:
        for r in range(rows):
            grid[r][c] = 1

    # Find which non-zero components touch fill lines
    comp_map = find_components(grid)
    changed_comps = []

    # Group cells by component ID
    comp_to_cells = {}
    for cell, comp_id in comp_map.items():
        if comp_id not in comp_to_cells:
            comp_to_cells[comp_id] = []
        comp_to_cells[comp_id].append(cell)

    for comp_id, comp_cells in comp_to_cells.items():
        touches_fill = False

        # Check if any cell is on a fill line
